import{St as e,at as t,it as n,n as r,st as i,vt as a}from"./chunks/framework.yntlMcNk.js";var o=JSON.parse(`{"title":"Catalogs","description":"","frontmatter":{"title":"Catalogs","covers":{"screens":["SCR-020","SCR-028"],"stories":["US-046","US-047","US-048","US-049","US-050","US-051","US-052","US-053","US-080"]}},"headers":[],"relativePath":"usage/catalogs.md","filePath":"usage/catalogs.md"}`),s={name:`usage/catalogs.md`};function c(r,o,s,c,l,u){let d=e(`Screenshot`);return a(),n(`div`,null,[o[0]||=t(`<h1 id="catalogs" tabindex="-1">Catalogs <a class="header-anchor" href="#catalogs" aria-label="Permalink to “Catalogs”">​</a></h1><p>A catalog is a reusable table view of the repository. It shows the entities of one entity type as rows. You need the permission <code>entity:read</code> (for example the role <code>viewer</code>) to see catalogs and create personal ones; shared catalogs need <code>catalog:manage</code> (role <code>enterprise-architect</code>).</p><p>The sidebar arranges catalogs in folders; <em>Place in navigation</em> on a catalog adds it there (see <a href="./navigation">Navigation tree</a>).</p><h2 id="create-a-catalog" tabindex="-1">Create a catalog <a class="header-anchor" href="#create-a-catalog" aria-label="Permalink to “Create a catalog”">​</a></h2><ol><li><p>Choose <em>Catalogs</em> in the header, then <em>New catalog</em>.</p></li><li><p>Fill in the dialog <em>New catalog</em>:</p><table tabindex="0"><thead><tr><th>Field</th><th>Meaning</th></tr></thead><tbody><tr><td>Name</td><td>required; unique within the instance, regardless of upper and lower case</td></tr><tr><td>Description</td><td>optional, up to 1000 characters</td></tr><tr><td>Primary entity type</td><td>required; its entities become the rows of the table</td></tr><tr><td>Visibility</td><td><em>Shared</em>: visible to all users of the instance (needs the permission to manage catalogs); <em>Personal</em>: visible only to you</td></tr><tr><td>Default join mode</td><td><em>Aggregate</em>: one row per entity, linked entities in one cell; <em>Rows</em>: one row per linked entity. Applies to joins added later</td></tr></tbody></table></li></ol>`,5),i(d,{name:`catalog-create`,alt:`Dialog New catalog with name, description, entity type and visibility`}),o[1]||=t(`<ol start="3"><li>Choose <em>Create catalog</em>. The new catalog opens.</li></ol><p>If the name is already taken, the dialog says so; choose another name. Without the permission to manage catalogs, <em>Shared</em> is not selectable.</p><h2 id="browse" tabindex="-1">Browse a catalog <a class="header-anchor" href="#browse" aria-label="Permalink to “Browse a catalog”">​</a></h2><p>The list <em>Catalogs</em> shows every catalog you may see, marked <em>Shared</em> or <em>Personal</em>. Open one to see its table:</p>`,4),i(d,{name:`catalogs`,alt:`List of catalogs`}),i(d,{name:`catalog-table`,alt:`Table of a catalog with application components`}),o[2]||=t(`<ul><li>Names of entity types, column headers and values of enum properties appear in your language where your organization has translated them (see <a href="./login#your-profile">Your profile</a>).</li><li>As long as no columns are configured (see <a href="#configure-columns">Configure columns</a>), the table shows the columns <em>Name</em> and – if the entity type has the property <em>Status</em> – <em>Status</em>.</li><li>Values of an enum property, such as <em>Status</em>, are sorted in the order of the values, not alphabetically; entries without a value come last.</li><li>Click a column header to sort: ascending, descending, and back to the default order.</li><li>The table shows 50 entries per page; use the pagination below the table to move between pages.</li><li>Sort and page are part of the address of the page. Back navigation, a reload or a shared link restore the same view; invalid values in the address are ignored and the first page is shown in the default order.</li><li>If the entity type has no entities yet, the table shows <em>No entries found</em>.</li><li>A column on a property whose values you may not see shows a lock in its header and empty cells; you cannot sort or filter by it (see <a href="./../administration/property-visibility">Property visibility</a>).</li><li>A column on a connection-based property shows the value only in the rows of entities connected to your element and an empty cell in the others. Sorting puts the empty cells last, and a filter on a value finds only rows where you see it.</li><li>A query that takes longer than the time limit of your installation (10 seconds by default) is cancelled, and the table shows <em>The query took too long</em>. Narrow the filters or switch joins to compact mode and try again.</li><li>Another person&#39;s personal catalog cannot be opened; it behaves like a catalog that does not exist (<em>Catalog not found</em>).</li></ul><p>Through the API, <code>GET /catalogs/{id}/query</code> returns the same rows with the parameters <code>page</code> (from 0), <code>pageSize</code> (1–200, default 50) and <code>sort</code> (<code>{field}:{asc|desc}</code>).</p><ul><li>A page with a following page carries <code>nextCursor</code>. Send it as <code>cursor</code> together with <code>page</code> + 1 to read the next page faster; the rows and the total are the same as with <code>page</code> alone.</li><li>A cursor is valid only for the same query (columns or view, sort, join modes, filters, page size) and until the catalog changes or the backend restarts. Otherwise the query answers 400 with <code>cursor</code> in <code>invalidFields</code>; repeat it without the cursor.</li><li>A column whose property you may not read has <code>readable: false</code> and <code>null</code> values; a sort or filter on it answers 400. A connection-based column is <code>readable: true</code> when your account is linked to an element, with <code>null</code> in the rows outside your scope.</li><li>A query above the time limit answers 503 with the problem type <code>urn:oea:problem:query-timeout</code> (<em>Query took too long</em>).</li></ul><h2 id="filters" tabindex="-1">Filters <a class="header-anchor" href="#filters" aria-label="Permalink to “Filters”">​</a></h2><p>Filters narrow the table to the entries you need, for example the active applications only. Every reader of a catalog can set filters; they change only your view, not the catalog.</p><ol><li><p>Choose <em>Add filter</em> above the table.</p></li><li><p>Choose the <em>Column</em>: every column of the table, including the columns of the joins (shown as <em>Join · Column</em>) and, in a <a href="#connection-catalogs">connection catalog</a>, the columns of the source and the target.</p></li><li><p>Choose the <em>Operator</em>. Only the operators that fit the values of the column are offered:</p><table tabindex="0"><thead><tr><th>Values of the column</th><th>Operators</th></tr></thead><tbody><tr><td>Text (name, description, text properties)</td><td><em>equals</em>, <em>not equals</em>, <em>contains</em>, <em>starts with</em>, <em>is one of</em>, <em>is none of</em>, <em>is empty</em>, <em>is not empty</em></td></tr><tr><td>Enum values, such as <em>Status</em></td><td><em>equals</em>, <em>not equals</em>, <em>is one of</em>, <em>is none of</em>, <em>is empty</em>, <em>is not empty</em></td></tr><tr><td>Yes or no</td><td><em>equals</em>, <em>not equals</em>, <em>is empty</em>, <em>is not empty</em></td></tr><tr><td>Numbers and dates (also <em>Created</em>, <em>Updated</em> and <em>Version</em>)</td><td><em>equals</em>, <em>not equals</em>, <em>greater than</em>, <em>less than</em>, <em>at least</em>, <em>at most</em>, <em>is empty</em>, <em>is not empty</em></td></tr></tbody></table></li><li><p>Enter or choose the <em>Value</em> and choose <em>Apply</em>. For <em>is one of</em> and <em>is none of</em>, choose several enum values, or separate several text values with commas.</p></li></ol><p>Each filter appears as a chip above the table, for example <em>Status equals active</em>; the <em>×</em> of a chip removes it. The total below the table counts only the entries that pass, and the table starts again at the first page.</p><ul><li>Text comparisons ignore upper and lower case. <em>not equals</em> and <em>is none of</em> also keep entries without a value.</li><li>Dates compare by day; <em>Created</em> and <em>Updated</em> use the day in UTC.</li><li><strong>Join columns:</strong> a filter on a column of a join keeps only the entries with at least one matching linked entity, and the join shows only the matching ones. A join without a filter stays complete.</li><li><strong>AND or OR:</strong> from two filters on, choose <em>All filters (AND)</em> or <em>Any filter (OR)</em>. With OR, an entry passes if any filter holds.</li><li>A table has at most 20 filters.</li><li><strong>The address:</strong> filters are part of the address of the page, like sort and page. Back navigation, a reload or a shared link show the same filtered view. A filter the catalog cannot apply, for example on a column that was removed, is dropped, and the table shows all entries.</li></ul><h3 id="saved-filters" tabindex="-1">Saved filters <a class="header-anchor" href="#saved-filters" aria-label="Permalink to “Saved filters”">​</a></h3><p>A catalog keeps named filters for quick selection, for example <em>Active systems only</em>:</p><ul><li><strong>Save:</strong> with the filters set, choose <em>Save filter</em>, enter a name and, optionally, a description, and choose <em>Save</em>. The name must be unique in the catalog, regardless of upper and lower case. A catalog has at most 50 saved filters.</li><li><strong>Use:</strong> <em>Saved filters</em> next to the chips lists them for every reader of the catalog. Choosing one replaces the filters of the table with its conditions and its AND or OR.</li><li><strong>Not available:</strong> a saved filter on a column the catalog no longer shows is marked <em>not available</em> and cannot be chosen. Removing a join also removes the conditions of saved filters on its columns, and a saved filter left without conditions.</li></ul><p>Saving filters follows the rules for configuring a catalog. A shared catalog needs the permission to manage catalogs (<code>catalog:manage</code>); in your own personal catalog you save them yourself. Without that right, <em>Save filter</em> is not offered; create a personal catalog to keep your own filters. Saved filters are recorded in the audit trail.</p><p>Through the API, <code>GET /catalogs/{id}/query</code> takes one <code>filter={key}:{operator}[:{value}]</code> per filter, for example <code>filter=status:eq:active</code>, <code>filter=source.name:contains:CRM</code> or <code>filter={joinId}.protocol:in:REST,SOAP</code>, and <code>filterMode=or</code>. The key is the column key of the result, the operator one of <code>eq</code>, <code>neq</code>, <code>contains</code>, <code>startsWith</code>, <code>in</code>, <code>notIn</code>, <code>isNull</code>, <code>isNotNull</code>, <code>gt</code>, <code>lt</code>, <code>gte</code> and <code>lte</code>; an invalid filter answers 400. <code>POST /catalogs/{id}/filters</code> saves a filter with <code>name</code>, <code>description</code>, <code>logicalOperator</code> and <code>expressions</code> (<code>attributePath</code>, <code>operator</code>, <code>value</code>), and <code>DELETE /catalogs/{id}/filters/{filterId}</code> removes it.</p><h2 id="views" tabindex="-1">Views <a class="header-anchor" href="#views" aria-label="Permalink to “Views”">​</a></h2><p>A view shows a catalog the way it is needed for a task, for example <em>Compact view</em> with only the name and the status of the active applications. It keeps the columns and their order, the filters with <em>All filters (AND)</em> or <em>Any filter (OR)</em>, the mode of each join and the sort.</p><ul><li><strong>Choose a view:</strong> <em>Views</em> next to the filters lists the views of the catalog for every reader. Choosing one shows its columns and sets its filters, join modes and sort. <em>All columns</em> leaves the view and keeps the filters.</li><li><strong>Change the view:</strong> you can still filter, sort and switch joins. The table keeps the columns of the view, and <em>(changed)</em> next to the selection shows that the table differs from the saved view.</li><li><strong>The default view:</strong> a catalog can mark one view as default. When you open the catalog, it shows the default view, unless the address already holds a view, sort, page, join mode or filter. A shared link therefore always shows what it was shared with.</li><li><strong>The address:</strong> the view is part of the address, like the filters and the sort.</li></ul><h3 id="save-and-manage-views" tabindex="-1">Save and manage views <a class="header-anchor" href="#save-and-manage-views" aria-label="Permalink to “Save and manage views”">​</a></h3><p>Views follow the rules for configuring a catalog: a shared catalog needs the permission to manage catalogs (<code>catalog:manage</code>); in your own personal catalog you save them yourself. Without that right, <em>Save view</em> and the dialog <em>Views</em> are not offered.</p><ol><li>Set up the table: filters, sort and join modes.</li><li>Choose <em>Save view</em>. Enter a name and, optionally, a description.</li><li>Under <em>Columns of the view</em>, choose the columns and their order with the arrow buttons. To include columns that the current view hides, choose <em>All columns</em> first.</li><li>Choose <em>Show this view when the catalog opens</em> to make it the default, and then <em>Save</em>.</li></ol><p>The name must be unique in the catalog, regardless of upper and lower case. A catalog has at most 20 views. Filters and a sort on columns you leave out are not saved.</p><p>In the dialog <em>Views</em>, <em>Make default</em> makes another view the default; the previous default loses the mark. The trash button removes a view; if it was the default, the catalog then has none.</p><p>A view that names a column, a join or a sort column the catalog no longer has shows as <em>not available</em> and cannot be chosen. Removing a join also removes its join modes, filters and sort from the views. Every change of a view is recorded in the audit trail.</p><p>Through the API, <code>POST /catalogs/{id}/views</code> saves a view with <code>name</code>, <code>description</code>, <code>columnOrder</code> (column keys), <code>filters</code> and <code>filterMode</code> (as for saved filters), <code>joinModeOverrides</code>, <code>sort</code> and <code>isDefault</code>. <code>PUT</code> and <code>DELETE /catalogs/{id}/views/{viewId}</code> replace and remove it. <code>GET /catalogs/{id}/query?view={viewId}</code> shows the columns of the view; its filters, modes and sort are passed as the usual parameters.</p><h2 id="configure-columns" tabindex="-1">Configure columns <a class="header-anchor" href="#configure-columns" aria-label="Permalink to “Configure columns”">​</a></h2><p>You decide which attributes a catalog shows, in which order and under which header. A shared catalog needs the permission to manage catalogs (<code>catalog:manage</code>, role <code>enterprise-architect</code>); your own personal catalog you configure yourself.</p><ol><li>Open the catalog and choose <em>Configure columns</em>.</li><li>The dialog lists every attribute of the entity type: the fields <em>Name</em>, <em>Description</em>, <em>External ID</em>, <em>Created</em>, <em>Updated</em> and <em>Version</em>, and every property assigned to the entity type, also the inherited ones.</li><li>Per row: <ul><li><em>Visible</em> shows or hides the column. A hidden column stays in the list, so you can show it again later.</li><li><em>Header</em> replaces the name of the attribute in the table, for example <em>Operational Status</em> for <em>Status</em>.</li><li><em>Sortable</em> decides whether readers may sort by the column.</li></ul></li><li>Change the order by dragging a row, or with the arrow buttons of a row.</li><li>Under <em>Default sort</em>, choose the column and direction the table is sorted by when nobody chose a sort.</li><li>Choose <em>Save</em>. At least one column must be visible.</li></ol><p>A property that is no longer assigned to the entity type shows as <em>Not available</em> and is removed when you save. Every change is recorded in the audit trail.</p><p>Through the API, <code>PUT /catalogs/{id}/columns</code> replaces the list. Each column names a field (<code>&quot;field&quot;: &quot;name&quot;</code>, <code>description</code>, <code>externalId</code>, <code>createdAt</code>, <code>updatedAt</code>, <code>entityVersion</code>) or a property (<code>&quot;propertyDefId&quot;: &quot;…&quot;</code>), with <code>displayLabel</code>, <code>visible</code>, <code>sortable</code> and at most one <code>defaultSortDirection</code> (<code>asc</code> or <code>desc</code>). An empty list restores the default columns.</p><h2 id="joins" tabindex="-1">Joins <a class="header-anchor" href="#joins" aria-label="Permalink to “Joins”">​</a></h2><p>A join shows related entities next to each entry of the catalog, for example all interfaces of an application. It follows a connection type of the metamodel, such as <em>Data Flow</em>. Joins are configured like columns: a shared catalog needs the permission to manage catalogs, your own personal catalog you configure yourself.</p><ol><li>Open the catalog and choose <em>Joins</em>. The dialog lists the joins of the catalog.</li><li>Choose <em>Add join</em> and go through the four steps: <ol><li><em>Connection type</em>: only connection types that connect the entity type of the catalog are offered.</li><li><em>Direction</em>: <em>Outgoing</em> follows connections that start at the entry, <em>Incoming</em> those that end at it, <em>Both directions</em> both; an entity reached in both directions is listed once.</li><li><em>Target type</em>: only entity types the connection type allows at its other end.</li><li><em>Name</em>, <em>Default mode</em> and the columns of the target type, chosen like in <a href="#configure-columns">Configure columns</a>. The name becomes the header above the columns of the join.</li></ol></li><li>Choose <em>Save</em>. The table shows the join as a group of columns.</li></ol><p><em>Edit</em> changes a join, <em>Remove</em> removes it. A join whose connection type or target type no longer exists or no longer connects the entity types shows as <em>Not available</em> and is left out of the table. A catalog has at most 10 joins. Every change is recorded in the audit trail.</p><h3 id="compact-or-rows" tabindex="-1">Compact or rows <a class="header-anchor" href="#compact-or-rows" aria-label="Permalink to “Compact or rows”">​</a></h3><p>Every join has the switch <em>Compact / Rows</em> in its header:</p><ul><li><em>Compact</em> shows one row per entry; a cell lists all linked entities, one per line. An entry without linked entities keeps its row with an empty cell.</li><li><em>Rows</em> shows one row per linked entity; the entry repeats. In this mode you can also sort by a column of the join, and the page counts rows.</li></ul><p>The switch changes only your view, not the catalog. It is part of the address of the page, like sort and page. With several joins in <em>Rows</em>, each combination of their linked entities gets a row of its own. The <em>Default mode</em> of a join, or else the default join mode of the catalog, applies when you open the catalog.</p><p>Through the API, <code>POST /catalogs/{id}/joins</code> adds a join with <code>name</code>, <code>connectionMetatypeId</code>, <code>joinDirection</code> (<code>outbound</code>, <code>inbound</code>, <code>both</code>), <code>targetMetatypeId</code>, <code>targetColumns</code> (like the columns, without default sort) and <code>defaultJoinMode</code> (<code>rows</code>, <code>aggregate</code> or <code>null</code>). <code>PUT</code> and <code>DELETE /catalogs/{id}/joins/{joinId}</code> change and remove it. The query returns the results of every join in <code>joinResults</code> under the ID of the join; <code>joinMode[{joinId}]=rows</code> switches a join for one query, and <code>sort={joinId}.{key}:asc</code> sorts by a join column in rows mode.</p><h2 id="connection-catalogs" tabindex="-1">Connection catalogs <a class="header-anchor" href="#connection-catalogs" aria-label="Permalink to “Connection catalogs”">​</a></h2><p>A catalog can also list connections, for example all data flows between applications. Choose a connection type as <em>Primary entity type</em> when you create the catalog; the dialog lists the entity types under <em>Elements</em> and the connection types under <em>Connections</em>.</p><ul><li>Each connection becomes a row. As long as no columns are configured, the table shows <em>Source</em>, <em>Name</em> and <em>Target</em>: the entity the connection starts at, the connection itself and the entity it ends at.</li><li><em>Configure columns</em> also lists the attributes of the source and the target, for example <em>Source: Vendor</em>. Offered are the fields and the properties of the entity types the connection type allows at that end, with their subtypes; a connection type without such a restriction offers every property. An entity at that end without the property shows an empty cell.</li><li>These columns sort like any other column. If the source or target has been deleted, its cells stay empty.</li><li>A join starts at the connection itself, for example from a data flow to the data objects it carries. If no connection type starts or ends at the connection type of the catalog, the dialog <em>Joins</em> says so.</li></ul><p>Through the API, a column of the source or target carries <code>&quot;endpoint&quot;: &quot;source&quot;</code> or <code>&quot;target&quot;</code>, and its key in the query is <code>source.{key}</code> or <code>target.{key}</code>, for example <code>sort=source.name:asc</code>.</p>`,41)])}var l=r(s,[[`render`,c]]);export{o as __pageData,l as default};